/**
 * printSkillV2 — pulled skill rendering for the terraform path. Consumes
 * the `NormalizedSkill` that `skillFromTf` produces and emits an
 * `apps/<app>/skills/<refName>.ts` authoring file: `skill` with tools
 * as `catalog` tokens (self-app) or a TODO literal (foreign apps — their
 * catalog may not exist in this workspace) and tool fields as
 * `catalog.<app>.fields.<key>`.
 *
 * Named identically to (but distinct from, different file/path) the legacy
 * AST-based `printSkillV2` in `print-skill.ts` — same precedent as
 * `entities/agent/deserializer/print-agent.ts` vs. `print-agent-v2.ts`.
 *
 * Unresolved field and automation platform ids print as `unsafePlatformId(...)`.
 */
import { quote } from "../../../../pull/util.js";
import { sdkPackageSpecifier } from "../../../internal/sdk-package.js";
import { safeIdentifier } from "../../../internal/safe-identifier.js";
const TOOL_FACTORY_BY_TYPE_KEY = {
    createRecord: "skillCreateRecord",
    searchAspect: "skillSearchRecords",
    searchTable: "skillSearchTable",
    updateRecord: "skillUpdateRecord",
    runAgent: "skillRunAgent",
    automation: "skillAutomation",
};
function safeMember(name) {
    return /^[A-Za-z_$][A-Za-z0-9_$]*$/.test(name) ? `.${name}` : `[${quote(name)}]`;
}
function safeKey(name) {
    return /^[A-Za-z_$][A-Za-z0-9_$]*$/.test(name) ? name : quote(name);
}
function searchTableLookupKey(aspectName, tableName) {
    return JSON.stringify([aspectName, tableName]);
}
function printRunAs(runAs, appRefName) {
    if ("currentUser" in runAs)
        return "{ currentUser: true }";
    if ("publisher" in runAs)
        return "{ publisher: true }";
    return `{ serviceAccount: serviceAccountRef({ app: catalog.${appRefName}, name: ${quote(runAs.serviceAccount.name)} }) }`;
}
export function printSkillV2(skill, opts) {
    const { appRefName } = opts;
    const crossOrg = opts.crossOrg === true;
    const factories = [
        ...new Set([
            ...skill.tools.map((t) => TOOL_FACTORY_BY_TYPE_KEY[t.typeKey]).filter(Boolean),
            ...(skill.tools.some((t) => t.runAs !== undefined && "serviceAccount" in t.runAs)
                ? ["serviceAccountRef"]
                : []),
        ]),
    ].sort();
    const usesUnsafePlatformId = skill.tools.some((tool) => tool.automationRawId !== undefined ||
        tool.target?.kind === "unresolved" ||
        tool.fields?.some((field) => field.rawFieldId !== undefined && !opts.foreignFieldRefsById?.has(field.rawFieldId)) === true ||
        (tool.filterVariables?.length ?? 0) > 0);
    const lines = [];
    lines.push("/**");
    lines.push(` * ${skill.name}`);
    lines.push(" *");
    lines.push(" * Auto-generated by EDK (v2 pull). Hand-edit freely; the generator is a");
    lines.push(" * one-shot starting point, not a live-binding view.");
    lines.push(" */");
    lines.push("");
    lines.push(`import { ${[...factories, "skill"].sort().join(", ")} } from ${JSON.stringify(sdkPackageSpecifier("agents/skills"))};`);
    if (usesUnsafePlatformId)
        lines.push(`import { unsafePlatformId } from ${JSON.stringify(sdkPackageSpecifier("core"))};`);
    lines.push(`import catalog from "@catalog";`);
    lines.push("");
    const identifier = safeIdentifier(skill.refName, "skill");
    lines.push(`const ${identifier} = skill({`);
    lines.push(`  name: ${quote(skill.name)},`);
    lines.push(`  app: catalog.${appRefName},`);
    lines.push(`  description: ${quote(skill.description)},`);
    if (skill.instructions !== "" ||
        ((skill.inputs === undefined || skill.inputs.length === 0) &&
            (skill.lookups === undefined || skill.lookups.length === 0))) {
        lines.push(`  instructions: ${quote(skill.instructions)},`);
    }
    if (skill.inputs !== undefined && skill.inputs.length > 0) {
        lines.push("  inputs: {");
        for (const input of skill.inputs) {
            const parts = [];
            if (input.description !== undefined) {
                parts.push(`description: ${quote(input.description)}`);
            }
            if (input.required !== undefined) {
                parts.push(`required: ${input.required}`);
            }
            lines.push(`    ${safeKey(input.name)}: { ${parts.join(", ")} },`);
        }
        lines.push("  },");
    }
    if (skill.lookups !== undefined && skill.lookups.length > 0) {
        lines.push("  lookups: [");
        for (const lookup of skill.lookups) {
            const parts = [`input: ${quote(lookup.input)}`, `tool: ${quote(lookup.tool)}`];
            if (lookup.source !== undefined) {
                parts.push(`source: ${quote(lookup.source)}`);
            }
            lines.push(`    { ${parts.join(", ")} },`);
        }
        lines.push("  ],");
    }
    if (skill.status !== undefined)
        lines.push(`  status: ${quote(skill.status)},`);
    if (skill.properties !== undefined) {
        lines.push(`  properties: ${JSON.stringify(skill.properties)},`);
    }
    if (skill.discovery !== undefined) {
        lines.push(`  discovery: ${JSON.stringify(skill.discovery)},`);
    }
    if (skill.tools.length > 0) {
        lines.push("  tools: [");
        for (const tool of skill.tools) {
            lines.push(...printTool(tool, appRefName, crossOrg, opts.foreignAppRefNames, opts.foreignElementRefNames, opts.foreignFieldRefsById, opts.foreignSearchTableRefsByName).map((l) => `    ${l}`));
        }
        lines.push("  ],");
    }
    lines.push("});");
    lines.push("");
    lines.push(`export default ${identifier};`);
    lines.push("");
    return lines.join("\n");
}
function fieldOwnerRef(tool, appRefName, foreignAppRefNames, foreignElementRefNames) {
    // `fields` (and therefore this) is only ever reached for createRecord/
    // searchAspect/updateRecord, which always carry a target — automation/
    // runAgent tools return before this point. The undefined branch only
    // exists to satisfy NormalizedSkillTool.target's now-optional type.
    if (tool.target === undefined || tool.target.kind === "self")
        return { kind: "catalog", expr: `catalog.${appRefName}` };
    if (tool.target.kind === "unresolved") {
        return { kind: "raw", entityType: "app", name: tool.target.uuid, refName: tool.target.uuid };
    }
    const entityKind = tool.target.kind === "foreignElement" ? "element" : "app";
    const refNames = tool.target.kind === "foreignElement" ? foreignElementRefNames : foreignAppRefNames;
    const foreignRefName = tool.target.refName ?? refNames?.get(tool.target.name);
    return foreignRefName !== undefined
        ? refNames?.get(tool.target.name) !== undefined
            ? { kind: "catalog", expr: `catalog.${foreignRefName}` }
            : {
                kind: "raw",
                entityType: entityKind,
                name: tool.target.name,
                refName: foreignRefName,
                ...(tool.target.namespace !== undefined && { namespace: tool.target.namespace }),
            }
        : { kind: "raw", entityType: entityKind, name: tool.target.name, refName: tool.target.name };
}
function printTool(tool, appRefName, crossOrg, foreignAppRefNames, foreignElementRefNames, foreignFieldRefsById, foreignSearchTableRefsByName) {
    const factory = TOOL_FACTORY_BY_TYPE_KEY[tool.typeKey] ?? "skillSearchRecords";
    const lines = [`${factory}({`];
    const targetRefName = tool.target?.kind === "self"
        ? appRefName
        : tool.target?.kind === "foreignElement"
            ? tool.target.refName ?? foreignElementRefNames?.get(tool.target.name)
            : tool.target?.kind === "foreignApp"
                ? tool.target.refName ?? foreignAppRefNames?.get(tool.target.name)
                : undefined;
    lines.push(`  name: ${quote(tool.name)},`);
    lines.push(`  description: ${quote(tool.description)},`);
    if (tool.status !== undefined)
        lines.push(`  status: ${quote(tool.status)},`);
    if (tool.startMessage !== undefined)
        lines.push(`  startMessage: ${quote(tool.startMessage)},`);
    if (tool.runAs !== undefined)
        lines.push(`  runAs: ${printRunAs(tool.runAs, appRefName)},`);
    if (tool.typeKey === "runAgent") {
        lines.push(`  agent: catalog.${appRefName}.agents${safeMember(tool.targetAgentKey ?? "")},`);
        lines.push(`  workerTaskPrompt: ${quote(tool.workerTaskPrompt ?? "")},`);
        lines.push("}),");
        return lines;
    }
    if (tool.typeKey === "automation") {
        lines.push(tool.automationRawId !== undefined
            ? `  automation: unsafePlatformId(${quote(tool.automationRawId)}),`
            : `  automation: catalog.${appRefName}.automations${safeMember(tool.automationKey ?? "")},`);
        const inputs = tool.inputs ?? [];
        const missingRequired = tool.missingRequiredInputs ?? [];
        if (inputs.length > 0 || missingRequired.length > 0) {
            // `missingRequiredInputs` names REQUIRED trigger parameters this tool
            // has no real mapping for on the platform — `AutomationToolV2` demands
            // every one be present, but there is no real data to print for them
            // (see skill-tool/from-tf.ts's doc comment: inventing an entry here
            // would get faithfully re-serialized to HCL by `elementum build` and
            // propose writing fake data onto a live tool). Print only the REAL
            // captured entries, verbatim, and — only when a required one is still
            // missing — cast the whole (possibly empty) object so the file still
            // compiles; the cast changes nothing about what gets built, since an
            // empty/absent `inputs` already round-trips to the same wire shape.
            lines.push("  inputs: {");
            for (const input of inputs) {
                const parts = [];
                if (input.displayName !== undefined && input.displayName !== input.parameterName) {
                    parts.push(`name: ${quote(input.displayName)}`);
                }
                parts.push(`description: ${quote(input.description ?? "")}`);
                if (input.required !== undefined)
                    parts.push(`required: ${input.required}`);
                lines.push(`    ${safeKey(input.parameterName)}: { ${parts.join(", ")} },`);
            }
            const cast = missingRequired.length > 0
                ? ` as any /* TODO: automation requires input(s) for ${missingRequired.map((n) => quote(n)).join(", ")} — this tool has no mapping configured on the platform; add real inputs and remove this cast before deploying */`
                : "";
            lines.push(`  }${cast},`);
        }
        if (tool.outputs !== undefined && tool.outputs.length > 0) {
            lines.push("  outputs: {");
            for (const output of tool.outputs) {
                const spec = output.displayName !== undefined && output.displayName !== output.workflowPropertyName
                    ? `{ name: ${quote(output.displayName)} }`
                    : "{}";
                lines.push(`    ${safeKey(output.workflowPropertyName)}: ${spec},`);
            }
            lines.push("  },");
        }
        lines.push("}),");
        return lines;
    }
    if (tool.target?.kind === "self") {
        // A search-table tool targets the ELEMENT that owns the table, so a "self"
        // target means the owning aspect IS that element — emit `element:`, not
        // `app:`. (A foreignApp target on a searchTable tool is malformed input:
        // apps never own search tables. It keeps printing `app:` below so tsc
        // rejects the emitted source loudly instead of mislabelling an app as an
        // element.)
        lines.push(`  ${tool.typeKey === "searchTable" ? "element" : "app"}: catalog.${appRefName},`);
    }
    else if (tool.target?.kind === "unresolved") {
        // Export couldn't resolve target_id to any portable app/element
        // reference (board issue #648) — keep the raw platform id visible via
        // the same unsafePlatformId() escape automation/field refs already use,
        // so build round-trips it directly instead of misreading it as a named
        // reference; cast past the type system since the field itself is a
        // strict CatalogRef.
        const entityKind = tool.typeKey === "searchTable" ? "element" : "app";
        lines.push(`  ${entityKind}: unsafePlatformId(${quote(tool.target.uuid)}) as any /* TODO: unresolved ${entityKind} - export couldn't resolve target_id to a portable reference; replace with a real ref before deploying */,`);
    }
    else if (tool.target !== undefined) {
        // Board issue #42: the target can be a foreign APP or a foreign
        // ELEMENT — each stub carries the right `__kind` and is looked up
        // against its own map, never conflated.
        const entityKind = tool.target.kind === "foreignElement" ? "element" : "app";
        const refNames = tool.target.kind === "foreignElement" ? foreignElementRefNames : foreignAppRefNames;
        const catalogRefName = refNames?.get(tool.target.name);
        if (catalogRefName !== undefined) {
            // The dependency is already pulled into this workspace (board issue
            // #40) — a typed token, not a stub.
            lines.push(`  ${entityKind}: catalog.${catalogRefName},`);
        }
        else {
            // The foreign app/element's catalog may not exist in this workspace —
            // a literal token compiles and deploys; swap for a catalog token when
            // available (`edk pull app`/`edk pull element` reports missing
            // dependencies like this one).
            const todo = crossOrg
                ? ` // TODO: cross-org clone — "${tool.target.name}" was resolved in the SOURCE org; verify it exists (with this name) in the destination org`
                : "";
            lines.push(`  ${entityKind}: { __kind: ${quote(entityKind)}, refName: ${quote(tool.target.refName ?? tool.target.name)}, name: ${quote(tool.target.name)}${tool.target.namespace !== undefined ? `, namespace: ${quote(tool.target.namespace)}` : ""} },${todo}`);
        }
    }
    if (tool.typeKey === "searchAspect") {
        lines.push(`  queryDescription: ${quote(tool.queryDescription ?? "")},`);
        if (tool.limit !== undefined)
            lines.push(`  limit: ${tool.limit},`);
    }
    if (tool.typeKey === "searchTable") {
        if (tool.searchTableKey !== undefined) {
            lines.push(`  table: catalog.${targetRefName ?? appRefName}.searchTables${safeMember(tool.searchTableKey)},`);
        }
        else {
            const targetNameOrUuid = tool.target?.kind === "foreignApp" || tool.target?.kind === "foreignElement"
                ? tool.target.name
                : tool.target?.kind === "unresolved" ? tool.target.uuid : undefined;
            const parent = tool.target?.kind === "self"
                ? appRefName
                : tool.target?.kind === "foreignApp" || tool.target?.kind === "foreignElement"
                    ? tool.target.refName ?? targetNameOrUuid ?? ""
                    : targetNameOrUuid ?? "";
            const lookupParent = tool.target?.kind === "self" ? appRefName : targetNameOrUuid ?? "";
            const typedTable = tool.searchTableName === undefined
                ? undefined
                : foreignSearchTableRefsByName?.get(searchTableLookupKey(lookupParent, tool.searchTableName));
            if (typedTable !== undefined) {
                lines.push(`  table: catalog.${typedTable.ownerRefName}.searchTables${safeMember(typedTable.tableKey)},`);
            }
            else {
                lines.push(`  table: { __kind: "searchTable", refName: ${quote(tool.searchTableName ?? "")}, name: ${quote(tool.searchTableName ?? "")}, parent: ${quote(parent)} },`);
            }
        }
        lines.push(`  queryDescription: ${quote(tool.queryDescription ?? "")},`);
        if (tool.limit !== undefined)
            lines.push(`  limit: ${tool.limit},`);
    }
    if ((tool.typeKey === "searchAspect" || tool.typeKey === "searchTable") && tool.filterVariables !== undefined && tool.filterVariables.length > 0) {
        lines.push("  filterVariables: [");
        for (const variable of tool.filterVariables) {
            lines.push(`    { id: unsafePlatformId(${quote(variable.id)}), name: ${quote(variable.name)}, description: ${quote(variable.description)}, required: ${variable.required} },`);
        }
        lines.push("  ],");
    }
    if (tool.typeKey === "updateRecord" && tool.handleDescription !== undefined) {
        lines.push(`  handleDescription: ${quote(tool.handleDescription)},`);
    }
    if (tool.fields !== undefined && tool.fields.length > 0) {
        const owner = fieldOwnerRef(tool, appRefName, foreignAppRefNames, foreignElementRefNames);
        lines.push("  fields: [");
        for (const f of tool.fields) {
            // A foreign/out-of-scope aspect's field has no field resource ei can
            // reference — it falls back to a bare platform id (board issue #169);
            // print the raw-id shape (SkillSearchRawIdField/SkillRecordRawIdField)
            // instead of a catalog token.
            const resolvedRaw = f.rawFieldId === undefined ? undefined : foreignFieldRefsById?.get(f.rawFieldId);
            const isRaw = f.key === undefined && resolvedRaw === undefined;
            // A field always belongs to the tool's TARGET, not necessarily the
            // owning app — `owner` (self/foreign-resolved/foreign-unresolved)
            // mirrors the `aspect:` resolution above.
            const parts = isRaw
                ? [`fieldId: unsafePlatformId(${quote(f.rawFieldId ?? "")})`]
                : resolvedRaw !== undefined
                    ? [`field: catalog.${resolvedRaw.ownerRefName}.fields.${resolvedRaw.fieldKey}`]
                    : owner.kind === "catalog"
                        ? [`field: ${owner.expr}.fields.${f.key}`]
                        : [
                            `field: { __kind: "field", refName: ${quote(f.key)}, name: ${quote(f.name ?? f.key)}, fieldType: "TEXT", ` +
                                `parent: ${quote(owner.refName)}, parentKind: ${quote(owner.entityType)}, parentName: ${quote(owner.name)}${owner.namespace !== undefined ? `, parentNamespace: ${quote(owner.namespace)}` : ""} }`,
                        ];
            parts.push(`name: ${quote(f.name ?? "")}`);
            parts.push(`description: ${quote(f.description ?? "")}`);
            if ((tool.typeKey === "createRecord" || tool.typeKey === "updateRecord") && f.required !== undefined) {
                parts.push(`required: ${f.required}`);
            }
            if (f.defaultValue !== undefined)
                parts.push(`defaultValue: ${quote(f.defaultValue)}`);
            const todo = isRaw
                ? " // TODO: raw platform field id - the field belongs to a foreign/out-of-scope aspect ei can't resolve to a reference"
                : owner.kind === "raw" && resolvedRaw === undefined
                    ? ` // TODO: foreign field — type unconfirmed (ei's elementum_field data source doesn't expose it) and refName is a best-effort guess; verify against "${owner.name}"`
                    : "";
            lines.push(`    { ${parts.join(", ")} },${todo}`);
        }
        lines.push("  ],");
    }
    lines.push("}),");
    return lines;
}
